import time
import logging
from concurrent import futures
import grpc

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("grpc_server")

# In production, these stubs are generated by grpcio-tools from proto/agent_validation.proto
# e.g.: python -m grpc_tools.protoc -I../proto --python_out=app --grpc_python_out=app ../proto/agent_validation.proto

class MockValidationResponse:
    def __init__(self, is_allowed, reason, risk_score, suggested_action, evaluation_latency_ms):
        self.is_allowed = is_allowed
        self.reason = reason
        self.risk_score = risk_score
        self.suggested_action = suggested_action
        self.evaluation_latency_ms = evaluation_latency_ms

class MockRiskScoreUpdate:
    def __init__(self, agent_id, live_anomaly_score, timestamp):
        self.agent_id = agent_id
        self.live_anomaly_score = live_anomaly_score
        self.timestamp = timestamp


class AgentValidationServicer:
    """
    gRPC Server implementation providing ultra-low-latency transaction
    validation and real-time anomaly streaming to the Spring Boot backend.
    """

    def ValidatePaymentIntent(self, request, context):
        start_time = time.time()
        logger.info(f"[gRPC] Received ValidationRequest for agent={request.agent_id}, amount={request.amount_paise} paise")

        # Business Rule 1: High amount threshold requires step-up auth
        amount_inr = request.amount_paise / 100.0
        
        if amount_inr > 50000.0:
            latency = int((time.time() - start_time) * 1000)
            return MockValidationResponse(
                is_allowed=False,
                reason="Amount exceeds automated mandate threshold; manual 2FA required",
                risk_score=0.85,
                suggested_action="STEP_UP_AUTH",
                evaluation_latency_ms=latency
            )

        # Business Rule 2: Normal automated approval
        latency = int((time.time() - start_time) * 1000)
        return MockValidationResponse(
            is_allowed=True,
            reason="AI heuristic risk check passed; mandate active",
            risk_score=0.08,
            suggested_action="APPROVE",
            evaluation_latency_ms=latency
        )

    def StreamRiskTelemetry(self, request, context):
        """Streaming RPC example: feeds continuous risk score updates."""
        logger.info(f"[gRPC] Client subscribed to risk telemetry stream for agent={request.agent_id}")
        
        for i in range(5):
            yield MockRiskScoreUpdate(
                agent_id=request.agent_id,
                live_anomaly_score=0.05 + (i * 0.01),
                timestamp=str(time.time())
            )
            time.sleep(1)


def serve(port=50051):
    """Starts the gRPC server with threadpool concurrency."""
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    # In full generated code: agent_validation_pb2_grpc.add_AgentValidationServiceServicer_to_server(AgentValidationServicer(), server)
    server.add_insecure_port(f"[::]:{port}")
    logger.info(f"🚀 gRPC Server started on port {port}")
    return server

if __name__ == "__main__":
    server = serve()
    server.start()
    server.wait_for_termination()
